class SyncEngine(
  private val io: CoroutineDispatcher = Dispatchers.IO,   // injected, so tests can swap it
  private val scope: CoroutineScope
) {
  private val mutex = Mutex()                              // not synchronized {}
  private var lastCursor: String? = null

  fun start() = scope.launch(io) {
    val page = api.fetch(mutex.withLock { lastCursor })
    mutex.withLock { lastCursor = page.next }

    withContext(Dispatchers.Main) {   // UI-visible state, main thread on iOS too
      state.value = page.items
    }
  }
}

