class PostCache(driver: SqlDriver) {
  private val q = AppDatabase(driver).postQueries

  // Reactive read: the context passed to mapToList is where the query executes
  fun posts(): Flow<List<Post>> = q.selectAll().asFlow().mapToList(Dispatchers.IO)

  // Blocking on whoever called us — on iOS that is usually the main thread
  fun postsNow(): List<Post> = q.selectAll().executeAsList()

  // Off the caller's thread, and one commit for the whole batch
  suspend fun save(posts: List<Post>) = withContext(Dispatchers.IO) {
    q.transaction { posts.forEach { q.upsert(it.id, it.title, it.savedAt) } }
  }
}

