// Swift can wrap this in do/catch and it still kills the app
class BadRepo(private val api: Api) {
  suspend fun load(id: String): Post = api.get(id)   // IOException, SerializationException…
}

// Declared: the listed type arrives as NSError, everything else is still fatal
class AnnotatedRepo(private val api: Api) {
  @Throws(AppError::class, CancellationException::class)
  suspend fun load(id: String): Post =
    try { api.get(id) } catch (e: IOException) { throw AppError.Offline }
}

// Preferred: failure is data, and the exported signature never throws
sealed interface LoadResult {
  data class Ok(val post: Post) : LoadResult
  data object Offline : LoadResult
  data class Failed(val message: String) : LoadResult
}

class Repo(private val api: Api) {
  suspend fun load(id: String): LoadResult =
    try {
      LoadResult.Ok(api.get(id))
    } catch (e: CancellationException) {
      throw e                                  // never swallow cancellation
    } catch (e: IOException) {
      LoadResult.Offline
    } catch (e: Throwable) {
      LoadResult.Failed(e.message ?: "unknown")
    }
}

