// commonMain — report while the failure is still a Kotlin object
class ReportingFacade(private val repo: Repo, private val log: Logger) {

  suspend fun load(id: String): LoadResult =
    try {
      LoadResult.Ok(repo.load(id))
    } catch (e: CancellationException) {
      throw e
    } catch (e: Throwable) {
      log.e(e) { "load failed for id=" + id }   // Kermit -> Logcat / os_log
      Sentry.captureException(e)                // Kotlin stack trace, not native frames
      LoadResult.Failed(e.message ?: "unknown")
    }

  // Ship this behind a debug menu and fire it once per release
  fun crashOnPurpose(): Nothing = throw IllegalStateException("symbolication smoke test")
}

