sealed interface AuthState {
  data object Anonymous : AuthState
  data class Authenticated(val token: String, val expiresIn: Int = 3600) : AuthState
}

fun describe(state: AuthState, verbose: Boolean = false): String = when (state) {
  is AuthState.Anonymous -> "anon"
  is AuthState.Authenticated -> if (verbose) state.token else "authed"
}

